// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Reproduction".

The image offers an abstract, artistic interpretation of a complex, modern industrial network.
It visually captures the dynamic interaction and interconnectedness of numerous machines and devices.
By translating the technical network into an aesthetic composition, the image conveys the complexity
of industrial processes and the human-machine interface.

The abstract symbols and their connections represent the hierarchical structure and functional
diversity within the system. The color palette, predominantly blues, beiges and grays, emphasizes
the industrial context, while red accents highlight critical components.

The empty squares, symbolizing active user interfaces, represent the human element in controlling and
monitoring the system. They visually represent the interventions that guide the network's operations.
The variety of symbols and their arrangement reflects the heterogeneous nature of the network, with each
element fulfilling a specific role.

The icons are rearranged every four seconds to represent a different production area.
*/

let theShader, dpr = window.devicePixelRatio, ww = window.innerWidth*dpr, wh = window.innerHeight*dpr, startRandom;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2434004/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
	startRandom = Math.random();
}

function draw() {
  // shader() sets the active shader with our shader
  shader(theShader);

  // here we're using setUniform() to send our uniform values to the shader
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
	theShader.setUniform("startRandom", startRandom); // each time the shader starts, make it unique

  // rect gives us some geometry on the screen
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; gl.enable(gl.DEPTH_TEST); gl.depthFunc(gl.LEQUAL);
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec4 aPosition;
void main() { gl_Position = aPosition * 2. - 1.; }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform float startRandom;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define MN min(R.x,R.y)
#define S smoothstep

// Smooth-Edge function for anti-aliasing
#define SE(v,s) S(s+1./MN,s-1./MN,v)

// The color palette. Experiment by changing the last vec3's values. ->
#define hue(a) (fract(n*22.22)>.94?vec3(.5,.05,.1):(.45+.3*cos(6.3*((a)+vec3(.3,.2,.1)*.2))))

// Returns a pseudo random value for a given x/y coordinate.
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}

// Returns a square at the given point p with an edge length of s.
float box(vec2 p, float s) {
	p=abs(p)-s;
	return length(max(p,.0))+min(.0,max(p.x,p.y));
}

// The main function of the fragment shader.
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0);

	// Controls ratio of the different levels and sets the animation speed and behavior.
	float lvl=2., tt=T*.25, t=mix(floor(tt),floor(tt)+1.,S(.9,1.,fract(tt)));

	// Initialize the zoom level of the picture by the chosen level.
	uv*=lvl;

	// The loop controls the depth of the system.

	for (float i=.0; i<4.; i++) {

		// Creates the unit vector of the grid cell (now p) and its id.
		vec2 id=floor(uv*lvl), p=uv-(id+.5)/lvl;

		// Use this version instead if you want it to be centered:
		//vec2 id=floor(uv*lvl+(i<1.?.5:.0)), p =uv-(id+(i<1.?.0:.5))/lvl;

		// Generates a random number between .0 and 1. specifically for the cell.
		float n=rnd(id+t+startRandom);

		// Controls the ratio of leaves to branches.
		// The larger the more leaves, the smaller the more detail shown.

		if (n<.75) {
			n=fract(n*14.56);

			// Controls the ratio of cirles to rectangles.
			// The larger the more circles, the smaller the more rectangles are shown.

			if (n<.25) {
				float d=SE(length((lvl<4. && fract(n*11.11)>.75)?fract(p*11.+.5)-.5:p),.45/lvl);
				col+=d*hue(n);
			} else {
				n=fract(n*12.345);

				// Controls the ratio of empty to filled rectangles.
				// The larger the more emty, the smaller the more filled rectangles are shown.

				if (n<.25 && lvl<32.) {
					float d=box(p,.39/lvl)-.04/lvl, e=d;
					d=S(.5,-.2,(abs(d)-.01/lvl)/abs(d));
					col+=(.25*lvl)*d*hue(n+e+.5*T*fract(n*33.33));
				} else {
					float d=box(p,.4/lvl)-.04/lvl;
					col+=SE(d,.002/lvl);
					col*=hue(n);
				}
			}
			break;
		} else {
			lvl*=2.;
		}
		lvl*=2.;
	}

	// Increase the black to a dark gray. Blend it cyclically to support the animation.
	col=max(mix(col,vec3(0),S(.8,1.15,sin(tt*6.283185307+2.21)*.5+.5)),.1);

	// Output the final color.
	O=vec4(col,1);
}

